import React from "react";
import ResultItem from "./resultemsComponent";

class Result extends React.Component {
    render() {
        return (
            <>
                <main className="container mt-4 pt-5">
                    <div className="container-fluid mt-5">
                            <ResultItem/>
                    </div>
                </main>
            </>
        );
    }
}
export default Result;
